<script setup lang="ts">
import { computed,reactive,ref,watch } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { ElMessageBox,ElMessage } from 'element-plus'
import { api,apiResult } from '../lib/api'
import { can,canGateway } from '../lib/auth'
import { dateTime,pretty,statusLabel } from '../lib/format'
import { address,canonicalUuid,enc,errorText,gattParameters,gattProtocol,hasCapability,loadChoices,stableKey,taskIntent,type Row,type Page } from '../features/gateway/utils'
const route=useRoute(),router=useRouter(),pageId=computed(()=>String(route.meta.pageId)),rows=ref<Row[]>([]),next=ref(''),snapshot=ref(''),loading=ref(false),busy=ref(false),error=ref(''),search=ref(''),gateways=ref<Row[]>([]),peers=ref<Row[]>([]),scopes=ref<Row[]>([]),gatewayId=ref(String(route.query.gatewayId||'')),edit=ref(false),editId=ref(''),editEtag=ref(''),formTab=ref('identity'),formKey=stableKey(),intent=taskIntent(),createdTask=ref<Row>(),selected=ref<Row>(),subscriptions=ref<Row[]>([]),triggers=ref<Row[]>([]),triggerDialog=ref(false)
const peerForm=reactive({displayName:'',deviceAddress:'',addressType:'PUBLIC',scopeId:'',state:'ACTIVE'})
const ruleForm=reactive({name:'',peerId:'',gatewayIds:[] as string[],enabled:false,priority:100,serviceUuid:'',wireBits:'' as number|string,characteristicUuid:'',minRssi:undefined as number|undefined,security:'UNENCRYPTED',maxAgeMs:5000,cooldownMs:30000})
const originalRule=ref<Row>({})
const gatt=reactive({type:'GATT_CONNECT',radio:'NRF54',deviceAddress:'',addressType:'PUBLIC',security:'UNENCRYPTED',connectionRef:'',serviceUuid:'',characteristicUuid:'',mode:'NOTIFY',timeoutMs:5000,writeMode:'WITH_RESPONSE',verification:'READBACK',encoding:'HEX',value:''})
const path=computed(()=>pageId.value==='P05'?'/api/v1/ble-peers':pageId.value==='P06'?'/api/v1/gatt-connections':'/api/v1/auto-connect-rules')
const title=computed(()=>pageId.value==='P05'?'蓝牙对端':pageId.value==='P06'?'GATT 连接与操作':'自动连接规则')
const currentGateway=computed(()=>gateways.value.find(g=>g.gatewayId===gatewayId.value))
const visible=computed(()=>rows.value.filter(r=>!search.value||JSON.stringify([r.displayName,r.name,r.deviceAddress,r.serviceUuid,r.connectionRef]).toLowerCase().includes(search.value.toLowerCase())).filter(r=>!route.query.peerId||pageId.value!=='P07'||r.peerId===route.query.peerId))
const protocol=computed(()=>gattProtocol(currentGateway.value)),legacy=computed(()=>protocol.value==='LEGACY')
const writeMaximum=computed(()=>legacy.value?3072:Math.min(512,selected.value?.attMtu?selected.value.attMtu-3:512))
watch(currentGateway,()=>{if(legacy.value&&!['GATT_READ','GATT_WRITE'].includes(gatt.type))gatt.type=hasCapability(currentGateway.value,'GATT_READ')?'GATT_READ':'GATT_WRITE';if(!legacy.value){gatt.writeMode='WITH_RESPONSE';if(gatt.verification==='APPLICATION_REPLY')gatt.verification='READBACK'}})
const currentPeer=computed(()=>peers.value.find(p=>p.peerId===ruleForm.peerId))
const requiredAuto=['GW32_CONTROL_PROFILE_1','GW32_CAPTURE_CONTEXT_1','NRF54_BLE_GATT_CENTRAL','NRF54_BLE_GATT_SERVICE_DISCOVERY','GATT_CONNECT']
function autoAllowed(g:Row){return g.state==='ACTIVE'&&canGateway('gatt:execute',g)&&canGateway('task:create',g)&&requiredAuto.every(c=>hasCapability(g,c))}
const actionPermission=computed(()=>currentGateway.value&&currentGateway.value.state==='ACTIVE'&&canGateway('gatt:execute',currentGateway.value)&&canGateway('task:create',currentGateway.value)&&hasCapability(currentGateway.value,gatt.type)&&(legacy.value?['GATT_READ','GATT_WRITE'].includes(gatt.type)&&!gatt.connectionRef:protocol.value==='GW32'&&hasCapability(currentGateway.value,gatt.radio+'_BLE_GATT_CENTRAL')))
const requiresReference=computed(()=>['GATT_SUBSCRIBE','GATT_UNSUBSCRIBE','GATT_DISCONNECT'].includes(gatt.type)||!!gatt.connectionRef)
const gattAllowed=computed(()=>!!actionPermission.value&&(!requiresReference.value||selected.value?.state==='ACTIVE')&&(!['GATT_SUBSCRIBE','GATT_UNSUBSCRIBE'].includes(gatt.type)||hasCapability(currentGateway.value,gatt.radio+'_BLE_GATT_NOTIFY')&&hasCapability(currentGateway.value,'GW32_CAPTURE_CONTEXT_1')))
let listEpoch=0
async function load(more=false){const epoch=++listEpoch;loading.value=true;error.value='';try{if(!more){rows.value=[];next.value=''}let q='?limit=50';if(pageId.value==='P06'&&gatewayId.value)q+='&gatewayId='+enc(gatewayId.value);if(more&&next.value)q+='&cursor='+enc(next.value);const p=await api<Page>(path.value+q);if(epoch!==listEpoch)return;rows.value=more?[...rows.value,...p.items]:p.items;next.value=p.nextCursor||'';snapshot.value=p.snapshotAt||'';if(pageId.value==='P06'&&selected.value){selected.value=rows.value.find(r=>r.gatewayId===selected.value?.gatewayId&&r.connectionRef===selected.value?.connectionRef);if(!selected.value)gatt.connectionRef=''}}catch(e){if(epoch===listEpoch)error.value=errorText(e)}finally{if(epoch===listEpoch)loading.value=false}}
async function choices(){const r=await Promise.allSettled([loadChoices('/api/v1/gateways'),loadChoices('/api/v1/ble-peers'),loadChoices('/api/v1/resource-scopes')]);if(r[0].status==='fulfilled')gateways.value=r[0].value;if(r[1].status==='fulfilled')peers.value=r[1].value;if(r[2].status==='fulfilled')scopes.value=r[2].value;const failure=r.find(v=>v.status==='rejected');if(failure?.status==='rejected')error.value=errorText(failure.reason)}
watch(()=>[route.meta.pageId,route.query.gatewayId],async()=>{listEpoch++;rows.value=[];next.value='';snapshot.value='';gatewayId.value=String(route.query.gatewayId||'');selected.value=undefined;gatt.connectionRef='';createdTask.value=undefined;edit.value=false;await choices();await load()},{immediate:true})
function newPeer(){editId.value='';editEtag.value='';Object.assign(peerForm,{displayName:'',deviceAddress:'',addressType:'PUBLIC',scopeId:'',state:'ACTIVE'});error.value='';edit.value=true}
async function editPeer(row:Row){try{const r=await apiResult<Row>('/api/v1/ble-peers/'+enc(row.peerId));editId.value=row.peerId;editEtag.value=r.etag;Object.assign(peerForm,r.data);error.value='';edit.value=true}catch(e){error.value=errorText(e)}}
async function savePeer(){try{if(!peerForm.displayName.trim()||!peerForm.scopeId)throw new Error('请填写名称和资源范围');if(!can('gatt:manage',peerForm.scopeId))throw new Error('没有此资源范围的管理权限');const body:Row=editId.value?{displayName:peerForm.displayName.trim(),state:peerForm.state}:{displayName:peerForm.displayName.trim(),scopeId:peerForm.scopeId,deviceAddress:address(peerForm.deviceAddress,peerForm.addressType,true),addressType:peerForm.addressType};busy.value=true;await api('/api/v1/ble-peers'+(editId.value?'/'+enc(editId.value):''),editId.value?'PATCH':'POST',body,{etag:editEtag.value,key:formKey({id:editId.value,...body})});edit.value=false;ElMessage.success('对端已保存');await choices();await load()}catch(e){error.value=errorText(e)}finally{busy.value=false}}
function newRule(){editId.value='';editEtag.value='';originalRule.value={};formTab.value='identity';Object.assign(ruleForm,{name:'',peerId:String(route.query.peerId||''),gatewayIds:[],enabled:false,priority:100,serviceUuid:'',wireBits:'',characteristicUuid:'',minRssi:undefined,security:'UNENCRYPTED',maxAgeMs:5000,cooldownMs:30000});error.value='';edit.value=true}
async function editRule(row:Row){try{const r=await apiResult<Row>('/api/v1/auto-connect-rules/'+enc(row.ruleId));newRule();originalRule.value={...r.data};editId.value=row.ruleId;editEtag.value=r.etag;Object.assign(ruleForm,r.data);ruleForm.gatewayIds=[...r.data.gatewayIds];ruleForm.wireBits=r.data.wireBits||'';ruleForm.characteristicUuid=r.data.characteristicUuid||'';ruleForm.minRssi=r.data.minRssi}catch(e){error.value=errorText(e)}}
async function saveRule(){try{if(editId.value)for(const k of ['wireBits','characteristicUuid','minRssi']){if(originalRule.value[k]!==undefined&&((ruleForm as Row)[k]===undefined||(ruleForm as Row)[k]===null||(ruleForm as Row)[k]===''))throw new Error('当前契约不能移除已设定的可选匹配条件；请建立替代规则后停用旧规则')} if(!ruleForm.name.trim()||!ruleForm.peerId||!ruleForm.gatewayIds.length)throw new Error('请填写规则名称、对端和至少一个网关');if(!currentPeer.value||!can('gatt:manage',currentPeer.value.scopeId))throw new Error('没有此对端的管理权限');const body:Row={name:ruleForm.name.trim(),gatewayIds:ruleForm.gatewayIds,enabled:ruleForm.enabled,priority:ruleForm.priority,serviceUuid:canonicalUuid(ruleForm.serviceUuid),security:ruleForm.security,maxAgeMs:ruleForm.maxAgeMs,cooldownMs:ruleForm.cooldownMs};if(!editId.value)body.peerId=ruleForm.peerId;if(ruleForm.wireBits)body.wireBits=Number(ruleForm.wireBits);if(ruleForm.characteristicUuid.trim())body.characteristicUuid=canonicalUuid(ruleForm.characteristicUuid);if(ruleForm.minRssi!==undefined&&ruleForm.minRssi!==null)body.minRssi=ruleForm.minRssi;if(ruleForm.enabled)await ElMessageBox.confirm('启用后，授权网关会根据新鲜广播自动尝试连接该对端。','确认启用自动连接',{type:'warning',confirmButtonText:'启用并保存',cancelButtonText:'返回'});busy.value=true;await api('/api/v1/auto-connect-rules'+(editId.value?'/'+enc(editId.value):''),editId.value?'PATCH':'POST',body,{etag:editEtag.value,key:formKey({id:editId.value,...body})});edit.value=false;ElMessage.success('规则已保存');await load()}catch(e){if(e!=='cancel'&&e!=='close')error.value=errorText(e)}finally{busy.value=false}}
async function toggleRule(row:Row){try{await ElMessageBox.confirm(row.enabled?'停用仅阻止后续触发，不会取消已创建的任务。':'启用后网关可能根据新鲜广播自动连接对端。',row.enabled?'停用规则':'启用规则',{type:'warning'});busy.value=true;const body={enabled:!row.enabled};await api('/api/v1/auto-connect-rules/'+enc(row.ruleId),'PATCH',body,{etag:'"'+row.revision+'"',key:formKey({id:row.ruleId,revision:row.revision,...body})});await load()}catch(e){if(e!=='cancel'&&e!=='close')error.value=errorText(e)}finally{busy.value=false}}
async function showTriggers(row:Row){try{triggers.value=await loadChoices('/api/v1/auto-connect-triggers?ruleId='+enc(row.ruleId));triggerDialog.value=true}catch(e){error.value=errorText(e)}}
function mayManageRule(row:Row){const peer=peers.value.find(p=>p.peerId===row.peerId);return !!peer&&can('gatt:manage',peer.scopeId)}
async function selectConnection(row:Row){subscriptions.value=[];selected.value=row;gatewayId.value=row.gatewayId;Object.assign(gatt,{connectionRef:row.connectionRef,radio:row.radio,deviceAddress:row.deviceAddress,addressType:row.addressType,type:'GATT_READ'});createdTask.value=undefined;try{const items=await loadChoices('/api/v1/gatt-subscriptions?gatewayId='+enc(row.gatewayId)+'&connectionRef='+enc(row.connectionRef));if(selected.value?.gatewayId===row.gatewayId&&selected.value?.connectionRef===row.connectionRef)subscriptions.value=items}catch(e:any){subscriptions.value=[];if(e.status!==404)error.value=errorText(e)}}
function newConnection(){selected.value=undefined;subscriptions.value=[];createdTask.value=undefined;Object.assign(gatt,{type:legacy.value?(hasCapability(currentGateway.value,'GATT_READ')?'GATT_READ':'GATT_WRITE'):'GATT_CONNECT',connectionRef:'',deviceAddress:'',addressType:'PUBLIC',radio:'NRF54',security:'UNENCRYPTED'})}
async function submitGATT(){try{if(!gattAllowed.value||!currentGateway.value)throw new Error('网关能力、作用域权限或连接状态不允许此操作');const params=gattParameters(currentGateway.value,gatt,selected.value);if(gatt.type==='GATT_WRITE')await ElMessageBox.confirm('将向所选对端写入 '+atob(params.valueBase64).length+' 字节。结果未知时不要重复写入。','确认蓝牙写入',{type:'warning',confirmButtonText:'创建写入任务',cancelButtonText:'返回'});if(gatt.type==='GATT_DISCONNECT')await ElMessageBox.confirm('断开将停止此连接的订阅通知。','确认断开',{type:'warning'});busy.value=true;error.value='';const request=intent({gatewayId:gatewayId.value,type:gatt.type,parameters:params});createdTask.value=await api('/api/v1/tasks','POST',request.body,{key:request.key});intent.clear();ElMessage.success('任务已创建，等待设备结果')}catch(e){if(e!=='cancel'&&e!=='close')error.value=errorText(e)}finally{busy.value=false}}
</script>
<template><div><header class="page-heading"><div><h1>{{title}}</h1><p class="muted">{{pageId==='P05'?'登记已授权的静态蓝牙对端':pageId==='P06'?'按网关能力管理连接、读写与通知':'显式授权对端、网关范围及服务 UUID'}}</p></div><div><el-button v-if="pageId==='P05'&&can('gatt:manage')" type="primary" @click="newPeer">登记对端</el-button><el-button v-if="pageId==='P07'&&can('gatt:manage')" type="primary" @click="newRule">新建规则</el-button><el-button @click="load()">刷新</el-button></div></header>
<el-alert v-if="error" :title="error" type="error" :closable="false" class="mb"/>
<div :class="{'connection-layout':pageId==='P06'}"><section class="panel"><div class="toolbar"><el-select v-if="pageId==='P06'" v-model="gatewayId" clearable filterable placeholder="全部可见网关" @change="selected=undefined;gatt.connectionRef='';load()"><el-option v-for="g in gateways" :key="g.gatewayId" :label="g.displayName||g.gatewayId" :value="g.gatewayId"/></el-select><el-input v-model="search" clearable placeholder="本页检索名称 / 地址 / UUID"/><el-button v-if="pageId==='P06'&&can('gatt:execute')" @click="newConnection">{{legacy?'新建临时操作':'新建连接'}}</el-button></div>
<el-table v-if="pageId==='P05'" :data="visible" v-loading="loading" stripe><el-table-column label="对端" min-width="170"><template #default="{row}"><strong>{{row.displayName}}</strong><div class="muted mono">{{row.peerId}}</div></template></el-table-column><el-table-column prop="deviceAddress" label="蓝牙地址" min-width="150"/><el-table-column prop="addressType" label="地址类型" width="120"/><el-table-column label="资源范围" min-width="130"><template #default="{row}">{{scopes.find(s=>s.scopeId===row.scopeId)?.name||row.scopeId}}</template></el-table-column><el-table-column label="状态"><template #default="{row}"><el-tag :type="row.state==='ACTIVE'?'success':'info'">{{statusLabel(row.state)}}</el-tag></template></el-table-column><el-table-column prop="revision" label="版本" width="70"/><el-table-column label="操作" min-width="150"><template #default="{row}"><el-button v-if="can('gatt:manage',row.scopeId)" link type="primary" @click="editPeer(row)">编辑</el-button><el-button link @click="router.push({path:'/auto-connect-rules',query:{peerId:row.peerId}})">相关规则</el-button></template></el-table-column></el-table>
<el-table v-else-if="pageId==='P07'" :data="visible" v-loading="loading" stripe><el-table-column label="规则" min-width="160"><template #default="{row}"><strong>{{row.name}}</strong><div class="muted">版本 {{row.revision}} · 优先级 {{row.priority}}</div></template></el-table-column><el-table-column label="对端 / 网关" min-width="200"><template #default="{row}"><div>{{peers.find(p=>p.peerId===row.peerId)?.displayName||row.peerId}}</div><div class="muted">{{row.gatewayIds.join(', ')}}</div></template></el-table-column><el-table-column label="服务 UUID" min-width="240"><template #default="{row}"><span class="mono">{{row.serviceUuid}}</span><div class="muted">{{row.wireBits?row.wireBits+' 位广播':'任意广播位宽'}} · {{row.maxAgeMs}} ms</div></template></el-table-column><el-table-column label="启用" width="90"><template #default="{row}"><el-tag :type="row.enabled?'success':'info'">{{row.enabled?'已启用':'已停用'}}</el-tag></template></el-table-column><el-table-column label="操作" min-width="180" fixed="right"><template #default="{row}"><el-button v-if="mayManageRule(row)" link type="primary" @click="editRule(row)">编辑</el-button><el-button v-if="mayManageRule(row)" link @click="toggleRule(row)">{{row.enabled?'停用':'启用'}}</el-button><el-button link @click="showTriggers(row)">触发记录</el-button></template></el-table-column></el-table>
<template v-else><el-table :data="visible" v-loading="loading" stripe highlight-current-row @row-click="selectConnection"><el-table-column label="对端 / 网关" min-width="155"><template #default="{row}"><strong>{{row.deviceAddress||'未知对端'}}</strong><div class="muted">{{row.gatewayId}}</div></template></el-table-column><el-table-column prop="radio" label="射频" width="90"/><el-table-column label="连接" min-width="210"><template #default="{row}"><span class="mono">{{row.connectionRef}}</span><div class="muted">MTU {{row.attMtu||'未知'}} · {{row.securityState||'未知安全状态'}}</div></template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="row.state==='ACTIVE'?'success':row.state==='UNKNOWN'?'warning':'info'">{{statusLabel(row.state)}}</el-tag></template></el-table-column></el-table><el-alert title="UNKNOWN 表示设备执行结果待核实；不会自动释放占用，也不应重复物理写入。" type="info" :closable="false" class="mb"/></template>
<div class="toolbar footer"><span class="muted">已加载 {{rows.length}} 条 · {{dateTime(snapshot)}}</span><el-button :disabled="!next||loading" @click="load(true)">加载下一页</el-button></div></section>
<aside v-if="pageId==='P06'" class="panel"><h3>{{selected?'操作所选连接':legacy?'兼容网关临时读写':'创建蓝牙连接'}}</h3><el-alert v-if="selected&&selected.state!=='ACTIVE'" title="连接不是 ACTIVE，依赖该引用的操作已禁用。请查看任务或发起设备诊断。" type="warning" :closable="false"/>
<el-alert v-if="legacy" title="使用兼容 1.0 临时读写契约，不下发射频和持久连接引用。写入及回验能力由设备固件执行。" type="info" :closable="false" class="mb"/><el-form label-position="top" @submit.prevent="submitGATT"><el-form-item label="目标网关"><el-select v-model="gatewayId" filterable :disabled="!!selected"><el-option v-for="g in gateways" :key="g.gatewayId" :label="g.displayName||g.gatewayId" :value="g.gatewayId"/></el-select></el-form-item><el-form-item label="动作"><el-select v-model="gatt.type" @change="createdTask=undefined"><el-option v-for="v in selected?[['GATT_READ','读取'],['GATT_WRITE','写入'],['GATT_SUBSCRIBE','订阅'],['GATT_UNSUBSCRIBE','取消订阅'],['GATT_DISCONNECT','断开']]:legacy?[['GATT_READ','临时连接读取'],['GATT_WRITE','临时连接写入']]:[['GATT_CONNECT','持久连接'],['GATT_READ','临时连接读取'],['GATT_WRITE','临时连接写入']]" :key="v[0]" :label="v[1]" :value="v[0]"/></el-select></el-form-item>
<el-form-item v-if="!legacy" label="射频"><el-select v-model="gatt.radio" :disabled="!!selected"><el-option label="nRF54" value="NRF54"/><el-option label="ESP32" value="ESP32"/></el-select></el-form-item>
<template v-if="!selected"><el-form-item label="对端地址"><el-input v-model="gatt.deviceAddress" placeholder="AA:BB:CC:DD:EE:FF"/></el-form-item><el-form-item label="地址类型"><el-select v-model="gatt.addressType"><el-option label="PUBLIC" value="PUBLIC"/><el-option label="RANDOM" value="RANDOM"/></el-select></el-form-item></template>
<el-form-item v-if="gatt.type==='GATT_CONNECT'" label="安全要求"><el-select v-model="gatt.security"><el-option label="不要求加密" value="UNENCRYPTED"/><el-option label="已绑定且加密" value="BONDED_ENCRYPTED"/></el-select></el-form-item>
<template v-if="!['GATT_CONNECT','GATT_DISCONNECT'].includes(gatt.type)"><el-form-item label="服务 UUID"><el-input v-model="gatt.serviceUuid" placeholder="180f 或 128 位 UUID"/></el-form-item><el-form-item label="特征 UUID"><el-input v-model="gatt.characteristicUuid" placeholder="2a19 或 128 位 UUID"/></el-form-item></template>
<el-form-item v-if="gatt.type==='GATT_SUBSCRIBE'" label="通知方式"><el-select v-model="gatt.mode"><el-option label="NOTIFY" value="NOTIFY"/><el-option label="INDICATE" value="INDICATE"/></el-select></el-form-item>
<template v-if="gatt.type==='GATT_WRITE'"><el-form-item v-if="legacy" label="写入方式"><el-select v-model="gatt.writeMode"><el-option label="带响应 WITH_RESPONSE" value="WITH_RESPONSE"/><el-option label="无响应 WITHOUT_RESPONSE" value="WITHOUT_RESPONSE"/></el-select></el-form-item><el-form-item label="写入字节编码"><el-select v-model="gatt.encoding"><el-option label="Hex" value="HEX"/><el-option label="Base64" value="BASE64"/></el-select></el-form-item><el-form-item label="写入值"><el-input v-model="gatt.value" type="textarea" placeholder="原始特征值字节"/></el-form-item><el-form-item label="验证方式"><el-select v-model="gatt.verification"><el-option label="读取回验 READBACK" value="READBACK"/><el-option v-if="legacy" label="应用回执 APPLICATION_REPLY（依赖设备实现）" value="APPLICATION_REPLY"/><el-option :label="legacy?'无回验 NONE':'仅写响应 NONE'" value="NONE"/></el-select></el-form-item><p class="muted">{{legacy?'兼容契约载荷上限':'WITH_RESPONSE；按协商 MTU 限制'}} {{writeMaximum}} 字节。{{legacy?'实际特征长度与写入模式仍由设备校验。':''}}</p></template>
<el-form-item label="操作超时 ms"><el-input-number v-model="gatt.timeoutMs" :min="100" :max="30000"/></el-form-item><p v-if="!gattAllowed" class="muted">当前网关能力、作用域权限或连接状态不允许此动作。</p><el-button type="primary" native-type="submit" :disabled="!gattAllowed||!!createdTask" :loading="busy">创建操作任务</el-button><el-button v-if="createdTask" @click="router.push('/tasks/'+createdTask.taskId)">查看执行结果</el-button></el-form>
<template v-if="selected"><h4>已登记订阅</h4><el-table :data="subscriptions" size="small"><el-table-column prop="characteristicUuid" label="特征 UUID" min-width="180"/><el-table-column prop="mode" label="方式"/><el-table-column prop="state" label="状态"/></el-table><el-button text @click="router.push({path:'/tasks',query:{gatewayId}})">查看网关任务与诊断</el-button></template></aside></div>
<el-drawer v-model="edit" :title="pageId==='P05'?(editId?'修改蓝牙对端':'登记蓝牙对端'):(editId?'修改自动规则':'新建自动规则')" size="580px" destroy-on-close><el-alert v-if="error" :title="error" type="error" :closable="false" class="mb"/>
<el-form v-if="pageId==='P05'" label-position="top" @submit.prevent="savePeer"><el-form-item label="对端名称"><el-input v-model="peerForm.displayName" maxlength="128"/></el-form-item><el-form-item label="蓝牙地址"><el-input v-model="peerForm.deviceAddress" :disabled="!!editId" placeholder="AA:BB:CC:DD:EE:FF"/></el-form-item><el-form-item label="地址类型"><el-select v-model="peerForm.addressType" :disabled="!!editId"><el-option label="PUBLIC" value="PUBLIC"/><el-option label="RANDOM（仅 random-static）" value="RANDOM"/></el-select></el-form-item><el-form-item label="资源范围"><el-select v-model="peerForm.scopeId" filterable :disabled="!!editId"><el-option v-for="s in scopes" :key="s.scopeId" :label="s.name" :value="s.scopeId" :disabled="!can('gatt:manage',s.scopeId)||s.state!=='ACTIVE'"/></el-select></el-form-item><el-form-item v-if="editId" label="状态"><el-radio-group v-model="peerForm.state"><el-radio value="ACTIVE">活动</el-radio><el-radio value="DISABLED">停用</el-radio></el-radio-group></el-form-item><el-alert title="停用对端不会自动断开已有连接。地址、类型和资源范围登记后不直接修改。" type="info" :closable="false"/><el-button native-type="submit" type="primary" :loading="busy" class="mt">保存对端</el-button></el-form>
<el-form v-else label-position="top" @submit.prevent="saveRule"><el-tabs v-model="formTab"><el-tab-pane label="对端与网关" name="identity"><el-form-item label="规则名称"><el-input v-model="ruleForm.name" maxlength="128"/></el-form-item><el-form-item label="注册对端"><el-select v-model="ruleForm.peerId" filterable :disabled="!!editId"><el-option v-for="p in peers" :key="p.peerId" :label="p.displayName+' · '+p.deviceAddress" :value="p.peerId" :disabled="p.state!=='ACTIVE'||!can('gatt:manage',p.scopeId)"/></el-select></el-form-item><el-form-item label="允许自动连接的网关"><el-select v-model="ruleForm.gatewayIds" multiple filterable><el-option v-for="g in gateways" :key="g.gatewayId" :label="(g.displayName||g.gatewayId)+(autoAllowed(g)?'':'（缺能力或权限）')" :value="g.gatewayId" :disabled="!autoAllowed(g)"/></el-select></el-form-item><el-button @click="formTab='match'">下一步：匹配条件</el-button></el-tab-pane>
<el-tab-pane label="匹配条件" name="match"><el-form-item label="服务 UUID"><el-input v-model="ruleForm.serviceUuid" placeholder="16 / 32 / 128 位 UUID，保存时规范化"/></el-form-item><el-form-item label="广播 UUID 位宽"><el-select v-model="ruleForm.wireBits"><el-option label="不限" value=""/><el-option v-for="n in [16,32,128]" :key="n" :label="n+' 位'" :value="n"/></el-select></el-form-item><el-form-item label="可选特征 UUID"><el-input v-model="ruleForm.characteristicUuid" placeholder="不填写则仅验证服务"/></el-form-item><el-form-item label="最低 RSSI（可空）"><el-input-number v-model="ruleForm.minRssi" :min="-127" :max="20"/></el-form-item><el-form-item label="优先级（较大优先）"><el-input-number v-model="ruleForm.priority" :min="0" :max="10000"/></el-form-item><el-button @click="formTab='safety'">下一步：执行条件</el-button></el-tab-pane>
<el-tab-pane label="执行条件" name="safety"><el-form-item label="安全要求"><el-select v-model="ruleForm.security"><el-option label="不要求加密" value="UNENCRYPTED"/><el-option label="已绑定且加密" value="BONDED_ENCRYPTED"/></el-select></el-form-item><el-form-item label="观测有效期 ms"><el-input-number v-model="ruleForm.maxAgeMs" :min="1000" :max="30000"/></el-form-item><el-form-item label="尝试冷却间隔 ms"><el-input-number v-model="ruleForm.cooldownMs" :min="30000" :max="86400000"/></el-form-item><el-form-item label="启用自动连接"><el-switch v-model="ruleForm.enabled"/></el-form-item><el-alert title="只接受新鲜、可连接的 nRF 广播及匹配 UUID 证据。停用仅阻止后续触发；已有任务不会取消。" type="info" :closable="false"/><p class="muted">本规则将允许 {{ruleForm.gatewayIds.length}} 个网关连接 {{currentPeer?.displayName||'所选对端'}}。</p><el-button native-type="submit" type="primary" :loading="busy">保存规则</el-button></el-tab-pane></el-tabs></el-form></el-drawer>
<el-dialog v-model="triggerDialog" title="持久化触发记录" width="900px"><el-table :data="triggers"><el-table-column prop="gatewayId" label="网关"/><el-table-column prop="ruleRevision" label="规则版本" width="90"/><el-table-column label="证据事件" min-width="200"><template #default="{row}"><div>ADV {{row.advEventId}}</div><div>UUID {{row.uuidEventId}}</div></template></el-table-column><el-table-column label="创建时间" min-width="160"><template #default="{row}">{{dateTime(row.createdAt)}}</template></el-table-column><el-table-column label="任务" min-width="160"><template #default="{row}"><el-button link type="primary" @click="router.push('/tasks/'+row.taskId)">{{row.taskId}}</el-button></template></el-table-column></el-table></el-dialog>
</div></template>
<style scoped>.page-heading{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:22px}h1{margin:0;font-size:26px}.panel{background:white;border:1px solid #e2e8f0;border-radius:12px;padding:22px;min-width:0}.toolbar{display:flex;gap:12px;margin-bottom:16px;align-items:center}.toolbar .el-input{max-width:340px}.toolbar .el-select{min-width:180px}.connection-layout{display:grid;grid-template-columns:minmax(0,1fr) 370px;gap:20px}.el-form .el-select{width:100%}.footer{justify-content:space-between;margin:16px 0 0}.muted{color:#64748b;font-size:13px;line-height:1.6}.mono{font-family:monospace;overflow-wrap:anywhere}.mb{margin-bottom:16px}.mt{margin-top:16px}h3{margin-top:0}@media(max-width:1150px){.connection-layout{grid-template-columns:1fr}}@media(max-width:700px){.page-heading,.toolbar{flex-wrap:wrap}}</style>
